// GENERATED BY HAND -- the AXI random-read probe bench.
//
// Measures the one number that decides whether a join's build side can live
// in DRAM: sustained RANDOM single-beat read rate as a function of how many
// reads are allowed in flight.
//
// Why this exists rather than reusing dau_axi_burst_reader: that reader
// issues a new address only once the previous is accepted
// (`&& !m_axi_arvalid`), so it holds ONE outstanding read. For sequential
// bursts that is right -- a single AR fetches many beats and the data
// streams back at full rate. For random single-beat probes it is fatal: the
// rate collapses to 1/latency, about 10M probes/s at a 100 ns round trip,
// which is 20-60x worse than the host does the same join.
//
// Little's law says the depth needed is rate x latency. Against the measured
// host bar (1.63-4.96 ns per probe row) that is 20-61 probes in flight
// aggregate, or roughly 2.5-7.7 per lane across eight lanes -- unremarkable
// for AXI ID tagging. This tile exists to replace that ASSUMED 100 ns with a
// measurement, by sweeping MAX_OUTSTANDING and reporting cycles per probe.
//
// Addresses are a pseudo-random LFSR walk masked into a window, so the
// access pattern defeats row-buffer locality the way a real hash probe does.
// A sequential sweep would measure the DRAM's best case and answer the wrong
// question.

`default_nettype none

module dau_axi_random_probe #(
    parameter int ADDR_WIDTH = 32,
    parameter int DATA_WIDTH = 64,
    // reads allowed in flight at once. The whole point of the bench: sweep
    // it and watch cycles-per-probe fall until the memory system, not the
    // pipeline, is the limit.
    parameter int MAX_OUTSTANDING = 8
) (
    input  wire logic                   clk,
    input  wire logic                   rst,

    input  wire logic                   start,
    // window the probes land in: address = base | (lfsr & mask & ~7)
    input  wire logic [ADDR_WIDTH-1:0]  window_base,
    input  wire logic [ADDR_WIDTH-1:0]  window_mask,
    input  wire logic [31:0]            probe_count,

    output logic                        busy,
    output logic                        done,
    // cycles from the first AR to the last R: the measurement
    output logic [31:0]                 elapsed_cycles,
    // high-water mark of reads actually in flight, so a run that never
    // reached MAX_OUTSTANDING reports that rather than looking like a
    // memory-system result
    output logic [15:0]                 peak_outstanding,
    // XOR of every returned word: proves the data arrived rather than the
    // addresses merely being accepted, and keeps the read from being
    // optimised away. A run whose checksum is zero read nothing.
    output logic [DATA_WIDTH-1:0]       read_checksum,
    // sticky: any non-OKAY response. A slave erroring early would otherwise
    // look like a very fast run.
    output logic                        slave_error,

    output logic [ADDR_WIDTH-1:0]       m_axi_araddr,
    output logic [7:0]                  m_axi_arlen,
    output logic [2:0]                  m_axi_arsize,
    output logic [1:0]                  m_axi_arburst,
    output logic                        m_axi_arvalid,
    input  wire logic                   m_axi_arready,
    input  wire logic [DATA_WIDTH-1:0]  m_axi_rdata,
    input  wire logic [1:0]             m_axi_rresp,
    input  wire logic                   m_axi_rlast,
    input  wire logic                   m_axi_rvalid,
    output logic                        m_axi_rready
);

    localparam int COUNT_WIDTH = $clog2(MAX_OUTSTANDING + 1);

    logic                    running;
    logic [31:0]             issued;
    logic [31:0]             returned;
    logic [COUNT_WIDTH-1:0]  outstanding;
    logic [31:0]             lfsr;

    // single-beat reads: one address, one data word, so every probe pays the
    // full round trip exactly as a hash probe would
    assign m_axi_arlen   = 8'd0;
    assign m_axi_arsize  = (DATA_WIDTH == 64) ? 3'd3 : 3'd2;
    assign m_axi_arburst = 2'b01;  // INCR, immaterial for a single beat
    assign m_axi_rready  = 1'b1;   // never stall the return path; the bench
                                   // measures the memory, not our backpressure

    wire issue_ok = running && (issued != probe_count) && (outstanding != MAX_OUTSTANDING[COUNT_WIDTH-1:0]);
    wire ar_fire  = m_axi_arvalid && m_axi_arready;
    wire r_fire   = m_axi_rvalid && m_axi_rready && m_axi_rlast;

    // xorshift over the window. The masked-off low bits keep every probe
    // naturally aligned to the data width.
    wire [31:0] lfsr_next = lfsr ^ (lfsr << 13) ^ ((lfsr ^ (lfsr << 13)) >> 17) ^ ((lfsr ^ (lfsr << 13) ^ ((lfsr ^ (lfsr << 13)) >> 17)) << 5);
    wire [ADDR_WIDTH-1:0] probe_address = window_base | ({{(ADDR_WIDTH > 32 ? ADDR_WIDTH - 32 : 0){1'b0}}, lfsr} & window_mask & ~{{(ADDR_WIDTH-3){1'b0}}, 3'b111});

    always_ff @(posedge clk) begin
        if (rst) begin
            running          <= 1'b0;
            busy             <= 1'b0;
            done             <= 1'b0;
            issued           <= 32'd0;
            returned         <= 32'd0;
            outstanding      <= '0;
            elapsed_cycles   <= 32'd0;
            peak_outstanding <= 16'd0;
            read_checksum    <= '0;
            slave_error      <= 1'b0;
            lfsr             <= 32'h1;
            m_axi_arvalid    <= 1'b0;
            m_axi_araddr     <= '0;
        end else begin
            done <= 1'b0;

            if (start && !running) begin
                running          <= 1'b1;
                busy             <= 1'b1;
                issued           <= 32'd0;
                returned         <= 32'd0;
                outstanding      <= '0;
                elapsed_cycles   <= 32'd0;
                peak_outstanding <= 16'd0;
                read_checksum    <= '0;
                slave_error      <= 1'b0;
                lfsr             <= 32'h2463_534a;  // any non-zero seed
            end

            if (running) begin
                elapsed_cycles <= elapsed_cycles + 32'd1;

                // hold AR until accepted, but -- unlike the burst reader --
                // do NOT wait for it before counting the next as issuable:
                // the outstanding counter is what gates issue, so up to
                // MAX_OUTSTANDING addresses can be in flight at once
                if (!m_axi_arvalid && issue_ok) begin
                    m_axi_arvalid <= 1'b1;
                    m_axi_araddr  <= probe_address;
                end else if (ar_fire) begin
                    lfsr   <= lfsr_next;
                    issued <= issued + 32'd1;
                    if (issue_ok && (issued + 32'd1 != probe_count) && (outstanding + 1 != MAX_OUTSTANDING[COUNT_WIDTH-1:0])) begin
                        m_axi_araddr  <= probe_address;  // back-to-back issue
                    end else begin
                        m_axi_arvalid <= 1'b0;
                    end
                end

                // outstanding tracks issued-minus-returned, and the high
                // water mark says whether the depth was ever reached
                case ({ar_fire, r_fire})
                    2'b10: outstanding <= outstanding + 1;
                    2'b01: outstanding <= outstanding - 1;
                    default: ;  // both or neither leaves it unchanged
                endcase
                if (ar_fire && !r_fire && (16'(outstanding) + 16'd1 > peak_outstanding)) begin
                    peak_outstanding <= 16'(outstanding) + 16'd1;
                end

                if (m_axi_rvalid && m_axi_rready) begin
                    read_checksum <= read_checksum ^ m_axi_rdata;
                    if (m_axi_rresp != 2'b00) slave_error <= 1'b1;
                end

                if (r_fire) begin
                    returned <= returned + 32'd1;
                    if (returned + 32'd1 == probe_count) begin
                        running <= 1'b0;
                        busy    <= 1'b0;
                        done    <= 1'b1;
                    end
                end
            end
        end
    end

endmodule

`default_nettype wire
